const E=LifeEngine,F=LifeFlow,KEY='lifeline-test-v1',labels={money:'Деньги',skill:'Навыки',health:'Здоровье',energy:'Силы',bond:'Близость',joy:'Радость'},icons={money:'◈',skill:'✧',health:'♡',energy:'ϟ',bond:'❋',joy:'☀'};let state,tab='story',trialOriginal=null,menuOpen=false;try{state=JSON.parse(localStorage.getItem(KEY));if(!state||state.v!==1||!state.origin)state=E.fresh();}catch{state=E.fresh();}if(state.goal&&!Number.isInteger(state.goal.step))state.goal=null;E.ensureChildhood(state);F.ensure(state);state.flow.playing=false;const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function birthplace(s=state){return esc(s.origin.country);}
function birthChance(s=state){return (s.origin.birthProbability*100).toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:4})+'%';}
function birthSourceLink(){return `<button class="birth-source-link" data-birth-source>${state.origin.birthDataYear?'Почему эта страна? ООН · '+state.origin.birthDataYear:'Как было выбрано место рождения?'}</button>`;}
function showBirthSource(){const d=E.birthData,o=state.origin;openDialog(`<span class="eyebrow">МЕСТО РОЖДЕНИЯ</span><h2>${birthplace()}</h2>${o.birthDataYear?`<p>В этой стране или территории оценено <strong>${o.births.toLocaleString('ru-RU')} живорождений</strong> за ${o.birthDataYear} год.</p><p>Её доля в выборке — <strong>${birthChance()}</strong>, примерно 1 из ${Math.round(1/o.birthProbability).toLocaleString('ru-RU')} рождений.</p><div class="forecast"><h3>Как выбирается страна</h3><p>Число рождений здесь ÷ сумма рождений во всех ${d.countryCount} странах и территориях набора. Чем больше рождений, тем выше вероятность.</p><p>Сумма весов: ${d.totalBirths.toLocaleString('ru-RU')}. Использованы оценки за ${d.year} год, с обновлением данных по Того. Регионы и мировые итоги исключены, чтобы не считать рождения дважды.</p></div>`:'<p>Это сохранение создано в старой версии: один из четырёх заранее заданных стартов выбирался с равными шансами. Этот выбор не был статистическим.</p><p>Чтобы получить место рождения по данным ООН, начните новую жизнь. Текущее сохранение автоматически не заменяется.</p>'}<p><a href="${d.sourceUrl}" target="_blank" rel="noopener">Источник: ООН, World Population Prospects 2024 ↗</a></p><p><a href="births-2023.csv" download>Скачать использованные веса стран (CSV)</a></p><p class="tiny">Статистика определяет страну или территорию. Город не выбирается: для него ещё нет отдельного набора данных. Имена и семейные истории художественные; благосостояние, отношения и параметры здоровья пока не откалиброваны по странам. Срез 2023 года не превращает дальнейшую историю в прогноз реальных событий.</p>`);}
function cohortView(){const c=LifeCohort.estimate(F.ensure(state).months,state.origin),percent=(c.probability*100).toLocaleString('ru-RU',{maximumFractionDigits:1});return `<div class="cohort-line"><p>Из родившихся с вами в один день ${c.world?'в мире':'в вашей стране'} живы <strong>≈ ${percent}%</strong></p><button class="birth-source-link" data-cohort-source aria-label="Как рассчитан процент живых ровесников">ⓘ</button></div>`;}
function showCohortSource(){const c=LifeCohort.estimate(F.ensure(state).months,state.origin);openDialog(`<span class="eyebrow">РОВЕСНИКИ · ${esc(c.world?'МИР':c.country.toUpperCase())}</span><h2>Оценка по таблице выживания</h2><p>Показана доля условной группы новорождённых, доживающая до возраста персонажа: l(x) ÷ l(0). Использована ${c.world?'мировая таблица, поскольку для страны сохранения не найдена отдельная':'таблица страны рождения — '+esc(c.country)} за ${c.year} год, оба пола.</p><p>Это модель при неизменной смертности ${c.year} года, а не подсчёт конкретных людей, родившихся в вашу игровую дату, и не прогноз жизни персонажа. Страна остаётся страной рождения.</p><p>Между целыми возрастами используется линейная интерполяция. Значения стран округлены до одного человека из 100 000, процент на экране — до десятых.</p><p><a href="https://population.un.org/wpp/" target="_blank" rel="noopener">Источник: ООН, World Population Prospects 2024 ↗</a></p><p class="tiny">CC BY 3.0 IGO. Таблица периодная. Индивидуальные решения не меняют статистическую долю ровесников.</p>`);}
function save(){if(trialOriginal){$('#save-status').textContent='Тестовая ситуация · основная жизнь сохранена';return;}try{localStorage.setItem(KEY,JSON.stringify(state));$('#save-status').textContent='✓ Сохранено на устройстве';}catch{$('#save-status').textContent='Сохранение недоступно';}}
function stage(){return state.age===0?'Рождение':state.age<6?'Первые годы':state.age<17?'Детство':state.age<32?'Начало пути':state.age<58?'Взрослая жизнь':'Новый ритм';}
function scene(){return renderPixelScene(state);}
function stats(){return Object.keys(labels).map(k=>`<div class="stat"><div><span>${icons[k]} ${labels[k]}</span><strong>${state.stats[k]}<small>/100</small></strong></div><div class="bar"><i style="width:${state.stats[k]}%;background:${state.stats[k]<30?'#b87964':'#8a9875'}"></i></div></div>`).join('');}
function goalCard(){if(state.age<6)return '';if(state.ended)return `<span class="eyebrow">БЛИЖАЙШИЕ ЦЕЛИ</span><h3>Достигнуто целей: ${state.completed.length}</h3>`;if(!state.goal)return `<button class="goal-empty" data-goal>＋ Выбрать ближайшую цель <span>${E.availableGoals(state).some(g=>g.suggested)?'Есть желание, связанное с вашими прежними интересами':'Можно выбрать позже или играть без цели'}</span></button>`;let g=state.goal;return `<div class="goal-head"><span class="eyebrow">ХОЧУ: ${E.chapters[state.step][0]} ЛЕТ</span><button class="text-btn" data-goal>Изменить</button></div><h3>${esc(g.name)}</h3><p class="goal-instruction">Чтобы выполнить цель, выберите действие<br><strong>«${esc(g.action)}»</strong> в текущей ситуации.</p>`;}
function ageText(age){const n=age%100,d=age%10;return age+' '+(n>=11&&n<=14?'лет':d===1?'год':d>=2&&d<=4?'года':'лет');}
function familyPanel(){const f=state.family;return `<div class="family-panel"><span class="eyebrow">ТЕ, КОГО ВЫ УЗНАЁТЕ ПЕРВЫМИ</span><div class="family-members"><span><i class="family-avatar mom">${PixelPeople.portrait(state,'mom')}</i><b>${esc(f.mother.name)}</b><small>мама · ${esc(F.occupation(state,'mother'))}</small></span><span><i class="family-avatar dad">${PixelPeople.portrait(state,'dad')}</i><b>${esc(f.father.name)}</b><small>папа · ${esc(F.occupation(state,'father'))}</small></span><span><i class="family-avatar gran">${PixelPeople.portrait(state,'gran')}</i><b>${esc(f.grandmother.name)}</b><small>бабушка · ${esc(F.occupation(state,'grandmother'))}</small></span></div></div>`;}
function personalityPanel(){let traits=E.traitSummary(state);if(!traits.length)return '';return `<div class="personality-panel"><span class="eyebrow">${state.age<6?'ПОСТЕПЕННО УЗНАЁМ ВАС':'ЧТО УЖЕ ЗАМЕТНО'}</span><p>${esc(state.origin.name)} ${traits.map(t=>esc(t.text)).join('; ')}.</p><small>Это наблюдения из вашей истории. Характер ещё будет меняться.</small></div>`;}
function decisionButton(kind,index,title,details='',disabled=false){const id=`decision-detail-${kind}-${index}`;return `<div class="decision-option"><button class="choice decision-button" data-${kind}="${index}" ${disabled?'disabled':''} ${details?`aria-describedby="${id}"`:''}>${esc(LifeChoiceCopy.title(title))}</button>${details?`<div class="decision-detail" id="${id}">${details}</div>`:''}</div>`;}
function earlyView(){const c=E.earlyScene(state);return `<div class="chapter-line"><span>ПЕРВЫЕ ГОДЫ · ${state.childhood.step+1} / 5</span><span>${ageText(c.age).toUpperCase()}</span></div><h2 class="event-title">${esc(c.title)}</h2><p class="event-desc early-story">${esc(c.text)}</p><div class="choices early-choices">${c.options.map((o,i)=>decisionButton('early',i,o.title)).join('')}</div>`;}
function choiceView(){const c=E.chapters[state.step];return `<div class="chapter-line"><span>ГЛАВА ${String(state.step+1).padStart(2,'0')} / ${E.chapters.length}</span><span>${c[0]} ЛЕТ</span></div><h2 class="event-title">${c[1]}</h2><p class="event-desc">${c[2]}</p><div class="choices">${c[3].map((o,i)=>decisionButton('choice',i,o.title)).join('')}</div>`;}
function peopleView(){const f=state.family;return `<div class="character-summary"><span class="eyebrow">ВАШ ПЕРСОНАЖ</span><h2>${esc(state.origin.name)}</h2><p>${birthplace()} · ${flowAge(F.ensure(state).months)} · ${esc(F.occupation(state))}</p>${birthSourceLink()}${cohortView()}</div><h2 class="event-title">Лица вашей жизни</h2>${familyPanel()}${socialPanel()}<div class="forecast"><h3>Как живётся дома</h3><p>${esc(f.home)}</p><p>${esc(f.climate)}</p></div>${state.age>=5?`<div class="person-card"><div class="avatar pixel-portrait">${PixelPeople.portrait(state,'friend')}</div><div><h3>Саша</h3><p>${state.age<17?'Школьник':state.age<22?'Учится на ветеринара':'Ветеринар'} · ${state.stats.bond>65?'вы часто проводите время вместе':'общение может стать ближе'}</p></div></div><p class="event-desc">${esc(state.childhood.moments.find(h=>h.age===5)?.text||'Впереди совместные игры и разговоры.')}</p>`:''}<p class="tiny">Достаток не определяет любовь и безопасность в семье. Поведение взрослых — их ответственность.</p>`;}
function modelView(){return `<h2 class="event-title">Что основано на данных</h2><div class="forecast"><h3>Страна рождения — статистика ООН</h3><p>Использованы оценки числа живорождений за ${E.birthData.year} год из World Population Prospects 2024, с обновлением для Того. В выборке ${E.birthData.countryCount} стран и территорий. Вероятность равна доле рождений страны в сумме весов набора.</p><p>Города не подставляются: для них нужен отдельный источник.</p>${birthSourceLink()}</div>${!state.origin.birthDataYear?'<p class="event-desc">Ваше сохранение создано до этого обновления. Его место рождения осталось прежним и не стало статистическим задним числом. Новый алгоритм работает при начале новой жизни.</p>':''}<h3>Течение времени — тест</h3><p class="event-desc">Время идёт по месяцам. Между решениями происходят повседневные события, рабочие и семейные изменения. Для важного выбора время останавливается. Пауза и скорость меняют просмотр; при закрытой вкладке время не идёт. Все новости в ленте — вымышленные события мира игры, не реальные новости страны.</p><h3>Ровесники в стране рождения</h3><p class="event-desc">Процент рассчитывается по таблице выживания ООН за 2023 год для страны рождения персонажа. Это условная группа при неизменной смертности 2023 года, а не подсчёт конкретных людей или прогноз жизни персонажа.</p><button class="birth-source-link" data-cohort-source>Как рассчитан процент ровесников?</button><h3>Остальные системы — тестовая модель</h3><p class="event-desc">Достаток семьи, отношения, характер, профессии, эффекты решений и события пока заданы для проверки игры. Национальных распределений доходов, образования, здоровья и семейных условий ещё нет. Все шкалы от 0 до 100 условны.</p><h3>Характер без ярлыков</h3><p class="event-desc">Ранние реакции помогают постепенно замечать интерес к исследованию, общению, выдумке или привычному ритму. Это авторская модель, а не психологический тест. Сложная семейная сцена не присваивает ребёнку черты характера.</p><h3>Привычки, соблазны и лечение — тест</h3><p class="event-desc">Предложения зависят от возраста, состояния и предыдущих действий. Краткое облегчение отделено от устойчивой радости; повторения могут усиливать тягу. Отказ доступен всегда. Антидепрессанты в согласованном лечении не усиливают тягу к веществам. Медицинские диагнозы и вероятности по этим игровым шкалам не рассчитываются.</p><button class="secondary" data-open-trial>Проверить ситуации: соблазн и лечение →</button><h3>Компании, семья и репутация — тест</h3><p class="event-desc">У знакомых разные интересы. Совместные дела сближают, а частые пропуски встреч могут отдалять. Достаток открывает часть связей, но не назначает характер или поведение. Репутация меняется от поступков и огласки. Партнёр может пересматривать взгляды; родительство необязательно. Детские трудности зависят от обстановки и поддержки и не предопределяются происхождением.</p><h3>Работа и обучение — тест</h3><p class="event-desc">Можно сравнивать предложения, совмещать учёбу с работой, развиваться в специальности, руководить, переучиваться и менять занятость. Опыт хранится отдельно по направлениям. Доход указан в условных единицах за квартал; зарплаты, требования и сроки ещё не откалиброваны по странам.</p><button class="secondary" data-open-trial>Проверить карьерные ситуации →</button><h3>Граница сценария</h3><p class="event-desc">Возраст 76 — фиксированный конец тестовой истории, не прогноз смерти. Исторические и будущие режимы ещё не подключены. Истории и имена художественные; они не описывают типичную жизнь всех жителей страны.</p><button class="secondary" id="export">Скачать историю жизни ↓</button>`;}
function ending(){return `<span class="eyebrow">ИСТОРИЯ ЗАВЕРШЕНА</span><h2 class="event-title">Жизнь сложилась<br>по-своему.</h2><p class="event-desc">${esc(state.origin.name)} · ${state.age} лет. Ваша история сохранена.</p><div class="comparison">${['health','money','joy'].map(k=>`<div><span>${labels[k]}</span><b>${state.baseline[k]} <i>→</i> ${state.stats[k]}</b></div>`).join('')}</div><button class="primary" id="album">Открыть историю жизни</button><button class="secondary" id="export">Скачать историю</button>`;}
// Small inline SVG: random star positions, three gently changing constellation maps.
// CSS owns animation; no frame loop, timers, video or external assets.
function birthSky(still=false){
 let skySeed=438;const rnd=(a,b)=>a+(still?((skySeed=(Math.imul(1664525,skySeed)+1013904223)>>>0)/4294967296):Math.random())*(b-a),circle=(x,y,r,extra='')=>`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${r}" ${extra}/>`;
 let stars='',maps='';
 for(let i=0;i<48;i++){let x=rnd(20,980),y=rnd(15,565);if(y>175&&x>260&&x<740)continue;stars+=circle(x,y,i%5===0?2:1.2,`style="--twinkle:${rnd(3,7).toFixed(1)}s;--delay:-${rnd(0,8).toFixed(1)}s"`);}
 for(let phase=0;phase<3;phase++){
  let shapes='';
  for(const [cx,cy] of [[175,105],[805,110],[130,425],[870,425]]){
   const points=Array.from({length:5},()=>[rnd(cx-85,cx+85),rnd(cy-65,cy+65)]);
   shapes+=`<path d="${points.map(([x,y],i)=>`${i?'L':'M'}${x.toFixed(1)},${y.toFixed(1)}`).join(' ')}"/>`+points.map(([x,y])=>circle(x,y,2.6)).join('');
  }
  maps+=`<g class="constellation-map" style="--phase:-${phase*8}s">${shapes}</g>`;
 }
 return `<svg class="birth-sky" viewBox="0 0 1000 580" preserveAspectRatio="${still?'none':'xMidYMid slice'}" aria-hidden="true" focusable="false"><g class="sky-stars">${stars}</g>${maps}</svg>`;
}
function birthScreen(){return `<section class="birth-screen">${birthSky()}<h1>Ваша история<br>ещё не началась<span>.</span></h1><p class="lead">Родитесь в случайной семье и узнайте,<br>с чего начнётся ваша жизнь.</p><button class="primary" id="be-born">Родиться</button><p class="tiny">Тест механик · данные демонстрационные</p></section>`;}
function familyConstellation(){
 const moving=!window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 const animate=(attribute,values)=>moving?`<animate attributeName="${attribute}" values="${values}" dur="9s" begin="2.4s" repeatCount="indefinite"/>`:'';
 return `<svg class="family-links" viewBox="0 0 520 260" preserveAspectRatio="none" aria-hidden="true"><path class="parent-link" d="M196 190 L260 218">${animate('d','M196 190 L260 218;M196 190 L258 216;M196 190 L262 220;M196 190 L260 218')}</path><path class="parent-link" d="M324 190 L260 218">${animate('d','M324 190 L260 218;M324 190 L258 216;M324 190 L262 220;M324 190 L260 218')}</path><path class="child-link" d="M260 218 L260 248">${animate('d','M260 218 L260 248;M258 216 L260 248;M262 220 L260 248;M260 218 L260 248')}</path><circle cx="260" cy="218" r="2.5">${animate('cx','260;258;262;260')}${animate('cy','218;216;220;218')}</circle><circle cx="260" cy="248" r="3"/></svg>`;
}
function birthIntroduction(){const info=BirthIntro.facts(state),chance=(info.chance*100).toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:4});return `<section class="birth-introduction" aria-labelledby="birth-welcome"><span class="eyebrow">НАЧАЛО ВАШЕЙ ЖИЗНИ</span><h1 id="birth-welcome" tabindex="-1">Всё началось с вас<span>.</span></h1><div class="birth-family"><div class="parent-orbits">${familyConstellation()}<div class="birth-parent birth-mother"><div class="parent-circle">${PixelPeople.portrait(state,'mom')}</div><span>${esc(state.family.mother.name)}</span><small>мама</small></div><div class="birth-parent birth-father"><div class="parent-circle">${PixelPeople.portrait(state,'dad')}</div><span>${esc(state.family.father.name)}</span><small>папа</small></div></div><div class="newborn-bubble"><div class="newborn-circle">${babyPortrait()}</div><h2>${esc(info.name)}</h2><span class="newborn-sex">${info.sex}</span><dl class="newborn-facts"><div><dt>Место рождения</dt><dd>${esc(info.country)} <button class="birth-info-button" data-birth-source aria-label="Почему эта страна">ⓘ</button></dd></div><div><dt>Игровая дата рождения</dt><dd>${esc(info.date)}</dd></div></dl></div></div><button class="primary continue-life" id="continue-life">Продолжить</button></section>`;}
function babyPortrait(){const skin=PixelPeople.skin(state);return `<svg viewBox="0 0 64 64" aria-hidden="true" shape-rendering="crispEdges"><path fill="#b1b9a4" d="M16 32h32v25H16z"/><path fill="#e4e8d7" d="M12 34h40v18H12zM18 52h28v8H18z"/><path fill="#f3f0dc" d="M15 34h10l25 15v5H39L15 40z"/><path fill="#7f9e95" d="M19 31h27v5H19z"/><path fill="${skin}" d="M21 9h22v4h5v17h-5v5H21v-5h-5V13h5z"/><path fill="#655247" d="M25 9h14v4H25zM23 20h3v3h-3zM38 20h3v3h-3zM30 28h5v2h-5z"/><path fill="#d08f7d" opacity=".6" d="M20 25h5v2h-5zM39 25h5v2h-5z"/></svg>`;}
function goMainMenu(){if($('#dialog').open)$('#dialog').close();if(trialOriginal){state=trialOriginal;trialOriginal=null;}F.ensure(state).playing=false;tab='story';menuOpen=true;$('#restart').disabled=false;save();render();}
function mainMenu(){const saved=state.started||state.birthIntroPending;return `<section class="main-menu-view">${birthSky(true)}<span class="eyebrow">ОДНА ЖИЗНЬ · МНОГО ПУТЕЙ</span><h1>lifeline</h1>${saved?`<p>${esc(state.origin.name)} · ${flowAge(F.ensure(state).months)}</p><button class="primary" id="resume-life">Продолжить жизнь</button>`:''}<button class="${saved?'secondary':'primary'}" id="menu-new-life">Новая жизнь</button></section>`;}
function openDialog(html){$('#dialog').className='';$('#dialog').innerHTML=`<div class="dialog-controls"><button class="text-btn" id="dialog-menu">В меню</button><button class="close icon" id="close-dialog" aria-label="Закрыть">×</button></div>${html}`;$('#dialog').showModal();$('#close-dialog').onclick=()=>$('#dialog').close();$('#dialog-menu').onclick=goMainMenu;}
function goalPicker(){if(state.age<6||state.ended)return;const goals=E.availableGoals(state);let selected=state.goal?.id||null;openDialog(`<div class="goal-modal-header"><span class="eyebrow">БЛИЖАЙШАЯ ЦЕЛЬ · ${E.chapters[state.step][0]} ЛЕТ</span><h2>${state.age<17?'Чего хочется ребёнку?':'Чего хочется сейчас?'}</h2><p>Выберите одно желание. Потом помогите персонажу выполнить его в игре.</p></div><div class="goal-modal-body"><div class="goal-options" role="radiogroup" aria-label="Ближайшая цель">${goals.map(g=>`<button class="goal-option ${selected===g.id?'selected':''}" role="radio" aria-checked="${selected===g.id}" data-pick="${g.id}"><span class="goal-radio" aria-hidden="true"></span><span><b>${esc(g.name)}</b>${g.suggested?`<span class="goal-match">${esc(g.reason)}</span>`:''}<small>Как выполнить: выбрать «${esc(g.action)}».</small></span></button>`).join('')}</div></div><div class="goal-modal-footer"><p id="goal-selection">${selected?'Выбрано: '+esc(state.goal.name):'Сначала выберите желание выше.'}</p><button class="primary" id="confirm-goal" ${selected?'':'disabled'}>Выбрать цель</button><button class="text-btn" id="no-goal">Пока без цели</button></div>`);$('#dialog').className='goal-dialog';document.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{selected=b.dataset.pick;document.querySelectorAll('[data-pick]').forEach(x=>{x.classList.toggle('selected',x.dataset.pick===selected);x.setAttribute('aria-checked',String(x.dataset.pick===selected));});$('#goal-selection').textContent='Выбрано: '+goals.find(g=>g.id===selected).name;$('#confirm-goal').disabled=false;});$('#confirm-goal').onclick=()=>{if(!selected)return;E.setGoal(state,selected);save();$('#dialog').close();render();};$('#no-goal').onclick=()=>{state.goal=null;save();$('#dialog').close();render();};}
const flowTypes={everyday:'Повседневность',family:'Семья',choice:'Ваш выбор',consequence:'Последствие',news:'Новости мира игры',career:'Работа',milestone:'Важное событие',goal:'Цель',event:'Событие',habit:'Привычки',care:'Поддержка',social:'Отношения'};
function flowAge(month){const years=Math.floor(month/12),months=month%12;return ageText(years)+(months?' '+months+' мес.':'');}
function lastImportantEvent(){return F.ensure(state).feed.filter(event=>LifeEventTone.describe(event).key).at(-1);}
function scenePlayback(){
 const f=F.ensure(state),p=F.pending(state),paused=p||!f.playing||state.ended,label=p?'Время остановлено: нужен ваш выбор':state.ended?'История завершена':paused?'Продолжить':'Пауза',locked=p||state.ended;
 const icon=(paths)=>`<svg viewBox="0 0 24 24" aria-hidden="true" fill="currentColor">${paths}</svg>`,button=(id,name,paths,disabled=false)=>`<button id="${id}" class="player-action" aria-label="${name}" title="${name}" ${disabled?'disabled':''}>${icon(paths)}</button>`;
 return `<div class="scene-player" role="group" aria-label="Управление временем">${button('previous-event','Последнее важное событие','<path d="M5 5h2v14H5zM18 5 8 12l10 7Z"/>',!lastImportantEvent())}${button('slower-time','Уменьшить скорость','<path d="m12 5-9 7 9 7Zm9 0-9 7 9 7Z"/>',f.speed<=1||locked)}${button('time-toggle',label,paused?'<path d="M9 5.5 19 12 9 18.5Z"/>':'<rect x="7" y="5" width="3" height="14" rx="1"/><rect x="14" y="5" width="3" height="14" rx="1"/>',locked)}${button('faster-time','Увеличить скорость','<path d="m3 5 9 7-9 7Zm9 0 9 7-9 7Z"/>',f.speed>=6||locked)}${button('next-event','К следующему событию','<path d="M17 5h2v14h-2zM6 5l10 7-10 7Z"/>',locked)}<button id="cycle-speed" class="player-action player-speed" aria-label="Скорость ${f.speed}×. Переключить скорость" ${locked?'disabled':''}>${f.speed}×</button></div>`;
}
function showPreviousEvent(){const event=lastImportantEvent();if(!event)return;state.flow.playing=false;save();render();openDialog(`<h2>Последнее важное событие</h2>${eventRow(event)}`);$('#dialog').addEventListener('close',()=>$('#previous-event')?.focus({preventScroll:true}),{once:true});}
function changeSpeed(direction){const speeds=[1,3,6],current=speeds.indexOf(F.ensure(state).speed),index=Math.max(0,Math.min(2,(current<0?0:current)+direction));state.flow.speed=speeds[index];save();render();}
function sphereIcon(key){const paths={health:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',finances:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M3 9h18M16 13h5v4h-5z"/>',relationships:'<circle cx="8" cy="7" r="3"/><circle cx="17" cy="9" r="2.5"/><path d="M2 21v-4a6 6 0 0 1 12 0v4M15 14a5 5 0 0 1 7 5v2"/>',hobbies:'<path d="M12 3a9 9 0 1 0 0 18h2a2 2 0 0 0 0-4h-1a2 2 0 0 1 0-4h4a4 4 0 0 0 4-4c0-4-5-6-9-6Z"/><circle cx="7" cy="10" r="1"/><circle cx="10" cy="6.5" r="1"/><circle cx="15" cy="7" r="1"/>',growth:'<path d="M12 6v15M12 6C9 3 5 3 2 4v15c4-1 7 0 10 2 3-2 6-3 10-2V4c-3-1-7-1-10 2Z"/>',joy:'<circle cx="12" cy="12" r="9"/><path d="M7 14a5 5 0 0 0 10 0M8 9h.01M16 9h.01"/>',energy:'<path d="m14 2-9 12h6l-1 8 9-12h-6z"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">${paths[key]||paths.joy}</svg>`;}
function happinessFace(value){return value<20?{id:'crying',name:'Плачущий'}:value<40?{id:'sad',name:'Грустный'}:value<60?{id:'neutral',name:'Спокойный'}:value<80?{id:'smiling',name:'Улыбающийся'}:{id:'laughing',name:'Смеющийся'};}
function statIcon(key){let pixels='',face=key==='joy'?happinessFace(state.stats.joy):null;const palette={'#':'#4f4149',p:'#f16b91',s:'#ba4268',h:'#ffe0e3',g:'#80ad79',l:'#cde2a2',d:'#4e765c',y:'#f4d97e',o:'#c89c57',w:'#fff2b6',b:'#88c5e0'};const pixel=(x,y,w,h,color)=>pixels+=`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${color}"/>`;
 if(key==='health'){const rows=['................','..###....###....','.#ppp#..#ppp#...','#phppp##phppp#..','#ppppppppphpp#..','#pppppppppppp#..','.#ppppppppps#...','..#ppppppps#....','...#ppppps#.....','....#ppps#......','.....#ps#.......','......##........'];rows.forEach((row,y)=>[...row].forEach((c,x)=>{if(palette[c])pixel(x+1,y+2,1,1,palette[c]);}));}
 else if(key==='money'){pixel(1,2,12,9,palette['#']);pixel(2,3,10,7,palette.d);pixel(3,5,12,9,palette['#']);pixel(4,6,10,7,palette.g);pixel(5,7,8,5,palette.l);pixel(6,8,6,3,palette.g);pixel(8,7,2,5,palette.w);pixel(7,8,4,3,palette.w);pixel(4,6,2,1,'#edf3d3');}
 else{pixel(5,1,6,1,palette['#']);pixel(3,2,10,1,palette['#']);pixel(2,3,12,2,palette['#']);pixel(1,5,14,6,palette['#']);pixel(2,11,12,2,palette['#']);pixel(3,13,10,1,palette['#']);pixel(5,14,6,1,palette['#']);pixel(5,2,6,1,palette.w);pixel(3,3,10,2,palette.y);pixel(2,5,12,6,palette.y);pixel(3,11,10,2,palette.y);pixel(5,13,6,1,palette.o);pixel(4,6,2,2,palette['#']);pixel(10,6,2,2,palette['#']);
 if(face.id==='crying'||face.id==='sad'){pixel(6,10,4,1,palette['#']);pixel(5,11,1,1,palette['#']);pixel(10,11,1,1,palette['#']);if(face.id==='crying'){pixel(4,8,1,3,palette.b);pixel(11,8,1,3,palette.b);}}
 else if(face.id==='neutral')pixel(5,10,6,1,palette['#']);else if(face.id==='smiling'){pixel(4,9,1,1,palette['#']);pixel(11,9,1,1,palette['#']);pixel(5,10,6,1,palette['#']);}else{pixel(4,9,8,2,palette['#']);pixel(5,11,6,1,palette['#']);pixel(6,12,4,1,palette['#']);pixel(6,11,4,1,palette.p);}}
 return `<svg viewBox="0 0 16 16" shape-rendering="crispEdges" data-pixel-icon="${key}" ${face?`data-face="${face.id}"`:''} aria-hidden="true">${pixels}</svg>`;}

const topStatNames={health:'Здоровье',money:'Деньги',joy:'Счастье'};
function topStats(){return `<div class="top-stats" role="group" aria-label="Показатели жизни">${Object.entries(topStatNames).map(([key,name])=>`<div class="top-stat-item"><button class="top-stat" data-stat="${key}" aria-label="${name}: ${state.stats[key]} из 100${key==='joy'?', '+happinessFace(state.stats.joy).name.toLowerCase()+' смайлик':''}" title="${name}">${statIcon(key)}</button><div class="top-stat-meter" role="progressbar" aria-label="${name}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${state.stats[key]}"><strong>${state.stats[key]}</strong><span class="top-stat-track"><i style="width:${state.stats[key]}%;background:${{health:'#cf8591',money:'#8da780',joy:'#c6ad6d'}[key]}"></i></span></div></div>`).join('')}</div>`;}
function showStatInfo(key){if(!topStatNames[key])return;const descriptions={health:'Текущее состояние здоровья. Фокус на здоровье помогает его поддерживать.',money:state.age<17?'Доступные ресурсы семьи. От них зависят покупки и возможности учиться.':'Ваши доступные ресурсы. Работа приносит доход, учёба и другие решения требуют расходов.',joy:'Насколько вы довольны своей жизнью. Выборы, близкие и увлечения влияют на счастье.'};openDialog(`<h2>${topStatNames[key]}</h2><p class="stat-detail-value">${state.stats[key]} <span>/ 100</span></p><div class="simple-track"><i style="width:${state.stats[key]}%;background:#8da780"></i></div><p>${descriptions[key]}</p>`);}

function showSphereInfo(){openDialog(`<h2>Ваши шкалы</h2><div class="sphere-explanations">${[['health','Здоровье','Текущее состояние здоровья.'],['finances','Финансы','Доступные ресурсы; в детстве — ресурсы семьи.'],['relationships','Отношения','Близость и поддержка со стороны окружающих.'],['hobbies','Хобби','Пока 8 баллов за каждый творческий выбор, сохранённый в истории.'],['growth','Саморазвитие','Навыки, полученные через обучение и практику.'],['joy','Счастье','Текущая радость и удовлетворённость жизнью.'],['energy','Силы','Запас энергии для повседневных дел.']].map(([key,name,desc])=>`<div><span class="area-icon">${sphereIcon(key)}</span><p><strong>${name}</strong><br>${desc}</p></div>`).join('')}</div><p>Шкалы от 0 до 100 могут расти и снижаться. При наличии причины появляются дополнительные состояния: любовь (близость в паре), облегчение, истощение и тяга к конкретной привычке.</p><p class="tiny">Все шкалы пока тестовые. Тяга сама по себе не означает диагноз зависимости.</p>`);}
function actionNotice(p){return `<div class="action-notice ${p?'choice-needed':''}" role="status"><i aria-hidden="true"></i><span>${state.ended?'История завершена':p?'Требуется ваш выбор':'Пока что ваших действий не требуется'}</span>${p?'<small>Время на паузе</small>':''}</div>`;}
function timeTutorial(){if(state.ended||F.pending(state)||state.uiHints?.timeSeen||state.flow.months>=12)return '';return `<aside class="time-tutorial" aria-label="Подсказка о времени"><span class="tutorial-symbol" aria-hidden="true">↠</span><div><strong>Время можно ускорить</strong><p>Когда выбор не требуется, нажмите «3×» или «6×», чтобы ускорить жизнь, либо «+ месяц», чтобы перейти на месяц вперёд. Для важного решения время остановится само.</p></div><button class="tutorial-dismiss" data-time-understood aria-label="Закрыть подсказку о времени">Понятно</button></aside>`;}
function timeUnderstood(){state.uiHints={...(state.uiHints||{}),timeSeen:true};}
function lifeProgress(){const month=F.ensure(state).months,current=Math.floor(month/12),ages=state.flow.decisions?Array.from({length:77},(_,i)=>i):[0,1,2,3,4,5,...E.chapters.map(c=>c[0])],previous=ages.filter(age=>age<=current).at(-1)||0,next=ages.find(age=>age>current)||76,progress=next===previous?100:Math.min(100,(month-previous*12)/((next-previous)*12)*100);return `<div class="life-progress" aria-label="До следующего этапа жизни"><span class="age-badge">${flowAge(month)}</span><span class="age-road"><i style="width:${progress}%"></i></span><span class="next-age">${ageText(next)}</span></div>`;}
function sceneTools(){return `<div class="scene-tools" role="group" aria-label="Меню сцены"><button id="scene-info" class="scene-tool" aria-label="Информация" title="Информация"><svg viewBox="0 0 16 16" shape-rendering="crispEdges" aria-hidden="true"><path d="M6 1h4v4H6zm0 6h4v7H6z" fill="#454b37"/><path d="M7 2h2v2H7zm0 6h2v5H7z" fill="#e8d778"/></svg></button><button id="scene-settings" class="scene-tool" aria-label="Настройки" title="Настройки"><svg viewBox="0 0 16 16" shape-rendering="crispEdges" aria-hidden="true"><path fill-rule="evenodd" d="M6 1h4v2h2V2h2v2h-1v2h2v4h-2v2h1v2h-2v-1h-2v2H6v-2H4v1H2v-2h1v-2H1V6h2V4H2V2h2v1h2Zm0 5v4h4V6Z" fill="#454b37"/></svg></button></div>`;}
function showSceneSettings(){const f=F.ensure(state),locked=Boolean(F.pending(state)||state.ended);openDialog(`<h2>Настройки</h2><label class="settings-speed">Скорость жизни<select id="settings-speed" ${locked?'disabled':''}>${[1,3,6].map(speed=>`<option value="${speed}" ${f.speed===speed?'selected':''}>${speed}×</option>`).join('')}</select></label>${locked?'<p class="tiny">Сначала завершите текущий выбор.</p>':''}<button class="secondary" id="settings-restart">Новая жизнь</button>`);$('#settings-speed').onchange=event=>{if(F.pending(state)||state.ended)return;state.flow.speed=Number(event.target.value);save();};$('#settings-restart').onclick=()=>{$('#dialog').close();$('#restart').click();};$('#dialog').addEventListener('close',()=>{render();$('#scene-settings')?.focus({preventScroll:true});},{once:true});}
function liveStage(){const f=F.ensure(state),p=F.pending(state);return `<div class="live-stage ${p||!f.playing||state.ended?'motion-paused':''}"><div class="live-visuals"><div class="live-scene-frame">${renderLiveScene(state)}${topStats()}${sceneTools()}<span class="activity-label">${F.names[F.activeScene(state)]}</span></div></div></div>`;}

function eventRow(ev){const tone=LifeEventTone.describe(ev);return `<article class="feed-row feed-${ev.type}${tone.key?' event-'+tone.key:''}"><span>${flowAge(ev.month)}</span><div><b>${flowTypes[ev.type]||'Событие'}${tone.label?`<span class="event-tone-label"> · ${tone.label}</span>`:''}</b><p>${esc(ev.text)}</p></div></article>`;}
function feedView(){const f=F.ensure(state),events=f.feed.slice(-4);return `<section class="live-feed" aria-label="Лента жизни"><div class="feed-heading"><span>${esc(state.origin.name)} · ${flowAge(f.months)}</span><button class="text-btn" id="all-events">Вся история</button></div><div class="feed-scroll">${events.length?events.map(eventRow).join(''):'<p class="feed-empty">Начался первый день вашей жизни. Скоро здесь появятся события.</p>'}${decisionReminder()}</div></section>`;}
function sideView(p){return `<div class="chapter-line"><span>МОМЕНТ ЖИЗНИ</span><span>ВРЕМЯ НА ПАУЗЕ</span></div><h2 class="event-title">${esc(p.title)}</h2><p class="event-desc">${esc(p.text)}</p><div class="choices">${p.options.map((o,i)=>decisionButton('side',i,o[0])).join('')}</div>`;}
function quietView(){const f=F.ensure(state);return `<div class="between-choices"><span class="eyebrow">МЕЖДУ РЕШЕНИЯМИ</span><h2>${state.age===0&&f.months<3?'Первые дни дома':'Жизнь продолжается'}</h2><p>${state.age===0&&f.months<3?`Мама ${esc(state.family.mother.name)} — ${esc(state.family.mother.job)}. Папа ${esc(state.family.father.name)} — ${esc(state.family.father.job)}. Пока ваш мир — это голоса и лица близких.`:'Сейчас решения не требуется. Можно наблюдать за персонажем, читать события или изменить скорость времени.'}</p>${state.age===0&&f.months<3?`<p>${esc(state.family.home)} ${esc(state.family.climate)}</p>`:''}<p class="tiny">Новости и повседневные события в этом тесте вымышленные. Страна рождения и оценка выживания ровесников основаны на данных ООН. Остальные системы пока тестовые.</p></div>`;}
function yearFocus(){const d=LifeDecisions.ensure(state),options=LifeDecisions.focuses(state);return options.length?`<label class="year-focus"><span>Фокус на год</span><select id="year-focus" aria-label="Фокус на год">${options.map(o=>`<option value="${o.id}" ${d.focus===o.id?'selected':''}>${o.title}</option>`).join('')}</select></label>`:'';}
function lifeChoiceView(p){return `<div class="chapter-line"><span>МОМЕНТ ЖИЗНИ</span><span>${ageText(state.age)}</span></div><h2 class="event-title">${esc(p.title)}</h2><p class="event-desc">${esc(p.text)}</p><div class="choices">${p.options.map((o,i)=>decisionButton('life',i,o.title,esc(o.hint),Boolean(o.disabled))).join('')}</div>`;}
function relationshipView(){return `<div class="chapter-line"><span>ВСТРЕЧА</span><span>${ageText(state.age).toUpperCase()}</span></div><h2 class="event-title">Алекс зовёт на свидание</h2><p class="event-desc">Вам приятно проводить время вместе.</p><div class="choices">${decisionButton('relationship',0,'На свидание')}${decisionButton('relationship',1,'Пока не хочу')}</div>`;}
function storyContent(){const p=F.pending(state);if(state.ended)return ending();return p?(p.kind==='life'?lifeChoiceView(p):p.kind==='relationship'?relationshipView():p.kind==='career'?careerChoiceView(p):p.kind==='habit'?habitChoiceView(p):p.kind==='social'?socialChoiceView(p):p.kind==='early'?earlyView():p.kind==='chapter'?choiceView():sideView(p)):quietView();}
function pendingDecisionKey(){const p=F.pending(state);return p?`${state.flow.months}:${p.kind}:${p.title||state.step}`:null;}
function deferredDecision(){const key=pendingDecisionKey();return Boolean(key&&state.uiHints?.deferredDecision===key);}
function deferDecision(){const key=pendingDecisionKey();if(!key)return;state.uiHints={...state.uiHints,deferredDecision:key};state.flow.playing=false;tab='story';menuOpen=false;save();render();$('.flow-main').scrollTop=0;$('[data-stat="health"]')?.focus({preventScroll:true});}
function returnToDecision(){if(state.uiHints)delete state.uiHints.deferredDecision;state.flow.playing=false;tab='story';save();render();}
function decisionReminder(){return deferredDecision()?`<article class="feed-row decision-return"><span>${flowAge(F.ensure(state).months)}</span><button id="return-decision">Вернуться к выбору</button></article>`:'';}
function decisionStage(){
 const p=F.pending(state);
 if(!p||state.ended||deferredDecision())return `<div class="story-deck"><div class="story-scroll">${feedView()}${state.ended?`<div class="flow-story">${ending()}</div>`:''}</div></div>`;
 const key=`${state.flow.months}:${p.kind}:${p.title||state.step}`,content=document.createElement('template');
 content.innerHTML=storyContent();
 const choices=content.content.querySelector('.choices');choices?.remove();
 return `<div class="story-deck has-decision"><div class="story-scroll">${feedView()}</div><section class="decision-panel flow-story" role="region" aria-labelledby="decision-title" data-decision-key="${esc(key)}"><button class="decision-close icon" id="close-decision" aria-label="Закрыть и решить позже">×</button><div class="decision-narrative">${content.innerHTML}</div><div class="decision-actions">${choices?.outerHTML||''}<button class="defer-decision" id="defer-decision">Решить позже</button></div></section></div>`;
}
function syncDecisionLayout(){const panel=$('.decision-panel');document.querySelectorAll('body>header,.top-stats,.flow-main>.tabs,.live-stage,.scene-player,.year-focus,.story-scroll,.info-screen').forEach(el=>{el.inert=Boolean(panel);});if(panel){panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');}}
document.addEventListener('keydown',event=>{const panel=$('.decision-panel[aria-modal="true"]');if(!panel||$('#dialog').open)return;if(event.key==='Escape'){event.preventDefault();deferDecision();return;}if(event.key!=='Tab')return;const buttons=[...panel.querySelectorAll('button:not(:disabled),a[href],[tabindex="0"]')],first=buttons[0],last=buttons.at(-1);if(!first)return;if(event.shiftKey&&(document.activeElement===first||!buttons.includes(document.activeElement))){event.preventDefault();last.focus();}else if(!event.shiftKey&&(document.activeElement===last||!panel.contains(document.activeElement))){event.preventDefault();first.focus();}});
function gameTabs(){return `<nav class="tabs" aria-label="Разделы игры">${[['story','Жизнь'],['history','История'],['people','Персонаж'],['model','Об игре']].map(([key,title])=>`<button data-tab="${key}" class="${key===tab?'active':''}">${title}</button>`).join('')}</nav>`;}
function render(){const f=F.ensure(state);if(!f.simple&&!trialOriginal){f.simple=true;f.relationshipSeen=Boolean(state.social?.partner)||f.months>=312;}if(!trialOriginal)LifeDecisions.ensure(state);if(menuOpen){$('#app').innerHTML=mainMenu();document.querySelector('body>header').inert=false;$('#resume-life')?.addEventListener('click',()=>{menuOpen=false;render();});$('#menu-new-life').onclick=()=>$('#restart').click();$('#resume-life')?.focus({preventScroll:true});return;}if(state.born&&!state.started&&!state.birthIntroPending)state.started=true;if(state.birthIntroPending){$('#app').innerHTML=birthIntroduction();$('#continue-life').onclick=()=>{delete state.birthIntroPending;F.begin(state);save();render();};document.querySelectorAll('[data-birth-source]').forEach(b=>b.onclick=showBirthSource);$('#birth-welcome').focus({preventScroll:true});return;}if(!state.started){$('#app').innerHTML=birthScreen();$('#be-born').onclick=()=>{BirthIntro.prepare(state,E.birthData.year);save();render();};return;}const active=document.activeElement?.id,previousChoice=$('.decision-panel')?.dataset.decisionKey;$('#app').innerHTML=`${trialOriginal?'<div class="trial-banner"><span>Тестовая ситуация · основная жизнь сохранена</span><button data-open-trial>Другая ситуация</button><button id="leave-trial">Вернуться к моей жизни →</button></div>':''}<div class="game-sky">${birthSky(true)}</div><div class="flow-layout game-shell"><section class="flow-main ${tab==='story'?'story-screen':'info-screen'}">${tab==='story'?'':gameTabs()}${tab==='story'?`${liveStage()}${scenePlayback()}${decisionStage()}${yearFocus()}${gameTabs()}`:tab==='history'?historyView():tab==='people'?simplePeopleView():simpleModelView()}</section></div>`;bind();const panel=$('.decision-panel'),heading=panel?.querySelector('.event-title');if(heading){heading.id='decision-title';heading.tabIndex=-1;}syncDecisionLayout();const log=$('.story-scroll .feed-scroll')||$('.story-scroll');if(log)log.scrollTop=log.scrollHeight;if(panel&&previousChoice!==panel.dataset.decisionKey)heading?.focus({preventScroll:true});else if(active&&$('#'+active))$('#'+active).focus({preventScroll:true});else if(previousChoice&&!panel&&tab==='story')($('#return-decision')||$('#time-toggle'))?.focus({preventScroll:true});}
function simplePeopleView(){const d=LifeDecisions.ensure(state);return `<h2 class="event-title">Близкие</h2><p class="event-desc">${esc(LifeDecisions.occupation(state))} · ${esc(d.home)}</p>${familyPanel()}${state.social?.partner?`<div class="person-card"><div class="avatar">А</div><div><h3>Алекс</h3><p>Ваш партнёр</p></div></div>`:''}`;}
function simpleModelView(){return `<h2 class="event-title">О вашей жизни</h2><p class="event-desc">Выберите фокус на год: он действует постепенно, пока идёт время. Важные события остановят жизнь и предложат короткий выбор.</p><p class="event-desc">Здоровье, деньги и счастье — три показателя вашей истории. Закрыть окно и выйти в меню можно в любой момент.</p><p class="tiny">Место рождения — по данным ООН за 2023 год. Остальные истории и игровые показатели вымышленные.</p>${birthSourceLink()}`;}
function historyView(){const f=F.ensure(state);return `<h2 class="event-title">История жизни</h2><p class="muted">Решения и то, что происходило между ними. Событий: ${f.feed.length}.</p><button class="secondary" id="export">Скачать всю историю</button><div class="history-feed">${decisionReminder()}${f.feed.slice(-100).reverse().map(eventRow).join('')||'<p class="empty">История только начинается.</p>'}</div>${f.feed.length>100?'<p class="tiny">Показаны последние 100 событий. Полная история доступна для скачивания.</p>':''}`;}
function bind(){$('#scene-settings')?.addEventListener('click',showSceneSettings);$('#scene-info')?.addEventListener('click',()=>openDialog(simpleModelView()));$('#cycle-speed')?.addEventListener('click',()=>{if(F.pending(state)||state.ended)return;const speeds=[1,3,6];state.flow.speed=speeds[(speeds.indexOf(state.flow.speed)+1)%speeds.length];save();render();});document.querySelectorAll('[data-stat]').forEach(button=>button.onclick=()=>showStatInfo(button.dataset.stat));$('#defer-decision')?.addEventListener('click',deferDecision);$('#return-decision')?.addEventListener('click',returnToDecision);$('#year-focus')?.addEventListener('change',event=>{if(LifeDecisions.setFocus(state,event.target.value)){save();render();}});$('#close-decision')?.addEventListener('click',deferDecision);$('#restart').disabled=false;document.querySelectorAll('[data-time-understood]').forEach(b=>b.onclick=()=>{timeUnderstood();save();render();});document.querySelectorAll('[data-sphere-info]').forEach(b=>b.onclick=showSphereInfo);document.querySelectorAll('[data-cohort-source]').forEach(b=>b.onclick=showCohortSource);document.querySelectorAll('[data-birth-source]').forEach(b=>b.onclick=showBirthSource);for(const kind of ['early','choice','side','relationship','life'])document.querySelectorAll('[data-'+kind+']').forEach(b=>b.onclick=()=>{if(F.resolve(state,Number(b.dataset[kind]))){if(state.uiHints)delete state.uiHints.deferredDecision;save();render();}});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;save();render();});document.querySelectorAll('[data-goal]').forEach(b=>b.onclick=goalPicker);document.querySelectorAll('[data-speed]').forEach(b=>b.onclick=()=>{state.flow.speed=Number(b.dataset.speed);timeUnderstood();save();render();});if($('#time-toggle'))$('#time-toggle').onclick=()=>{state.flow.playing=!state.flow.playing;save();render();};$('#previous-event')?.addEventListener('click',showPreviousEvent);$('#slower-time')?.addEventListener('click',()=>changeSpeed(-1));$('#faster-time')?.addEventListener('click',()=>changeSpeed(1));$('#next-event')?.addEventListener('click',()=>{state.flow.playing=false;F.advanceToEvent(state);save();render();});if($('#all-events'))$('#all-events').onclick=()=>{tab='history';render();};if($('#album'))$('#album').onclick=()=>{tab='history';render();};if($('#export'))$('#export').onclick=download;}
function download(){const text='lifeline — ПРОТОТИП\n'+state.origin.name+', '+state.origin.country+'\nПрофессия / занятие: '+F.occupation(state)+'\nНовости мира игры вымышлены.\n\n'+F.ensure(state).feed.map(e=>flowAge(e.month)+' · '+(flowTypes[e.type]||'Событие')+'\n'+e.text).join('\n\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='lifeline-story.txt';a.click();URL.revokeObjectURL(url);}
let tickElapsed=0,lastFrame=Date.now();setInterval(()=>{const now=Date.now(),dt=Math.min(250,now-lastFrame);lastFrame=now;const f=F.ensure(state);if(menuOpen||!state.started||state.ended||!f.playing||tab!=='story'||document.hidden||$('#dialog').open||F.pending(state)){tickElapsed=0;return;}tickElapsed+=dt*f.speed;if(tickElapsed>=3000){tickElapsed-=3000;if(F.advanceYear(state)){save();render();}}},100);

$('#restart').onclick=()=>{openDialog('<h2>Начать другую жизнь?</h2><p class="muted">Текущее сохранение на этом устройстве будет заменено. Историю можно предварительно скачать.</p><button class="secondary" id="keep-history">Скачать историю</button><button class="primary" id="confirm-restart">Начать заново →</button>');$('#keep-history').onclick=download;$('#confirm-restart').onclick=()=>{state=E.fresh();F.ensure(state).simple=true;menuOpen=false;tab='story';save();$('#dialog').close();render();};};$('#help').onclick=()=>openDialog(simpleModelView());$('#main-menu').onclick=goMainMenu;$('.brand').onclick=event=>{event.preventDefault();goMainMenu();};render();
